from pathlib import Path
import hashlib,json
root=Path.cwd()
for p in reversed(root.parents):
 f=p/'AGENTS.md'
 if f.is_file(): print(str(f)+'\\n'+f.read_text())
f=root/'AGENTS.md'
if f.is_file(): print(str(f)+'\\n'+f.read_text())
snapshot={str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for p in root.rglob('*') if p.is_file() and '.git' not in p.relative_to(root).parts}
Path('/private/tmp/proj-codex-before.json').write_text(json.dumps(snapshot))
PY"

